inline bool operator==(const MatchRecord& l, const MatchRecord& r) noexcept {
  return l.key == r.key && l.round == r.round && l.player_a == r.player_a &&
         l.player_b == r.player_b && l.ticks == r.ticks &&
         l.score_a == r.score_a && l.score_b == r.score_b &&
         l.lines_a == r.lines_a && l.lines_b == r.lines_b &&
         l.winner == r.winner;
}

SqlResult put(const study_net::MatchRecord& record, const RewardHook& hook={}) {
    study_net::MatchSubmission validator(0);
    if (!validator.prepare(record))
        return {SqlStatus::invalid, {}};
    std::lock_guard<std::mutex> lock(mutex_);
    try {
        ImmediateTransaction transaction(db_);
        if (const auto found = read_match(record.key)) {
            if (found->record != record)
                return {SqlStatus::conflict, {}};
            const auto saved=read_awards(record.key);
            if(!saved)throw std::runtime_error("saved award receipt missing");
            return {SqlStatus::accepted,
                    {record.key, found->row, record.player_a, record.player_b}, *saved};
        }

struct SavedAwards { int a=0; int b=0; int policy=0; };

struct SqlResult {
    SqlStatus status = SqlStatus::storage_error;
    study_net::Receipt receipt{};
    SavedAwards awards{};
};

std::optional<SavedAwards> read_awards(std::uint64_t key) {
    Statement q(db_.get(),
        "SELECT a.bp_delta,b.bp_delta,a.policy,b.policy FROM matches m "
        "JOIN match_rewards a ON a.match_id=m.id AND a.player_id=m.player_a "
        "JOIN match_rewards b ON b.match_id=m.id AND b.player_id=m.player_b WHERE m.match_key=?1");
    q.text(1,std::to_string(key));
    if(!q.next())return std::nullopt;
    const auto a=q.integer_column(0), b=q.integer_column(1), policy=q.integer_column(2);
    if(a<0 || a>10 || b<0 || b>10 || policy<0 || policy>1 || policy!=q.integer_column(3))
        throw std::runtime_error("invalid saved awards");
    const bool pair_ok=policy==0 ? a==0 && b==0
        : (a==0 && b==0) || (a==10 && b==3) || (a==3 && b==10);
    if(!pair_ok)throw std::runtime_error("invalid saved award pair");
    return SavedAwards{static_cast<int>(a),static_cast<int>(b),static_cast<int>(policy)};
}

struct Settlement {
    study_net::Receipt match;
    std::uint32_t bp_a = 0;
    std::uint32_t bp_b = 0;
    std::uint32_t policy = 0;
};

inline Json settlement_json(const Settlement& settlement) {
    Json json = receipt_json(settlement.match);
    json["bp_a"] = settlement.bp_a;
    json["bp_b"] = settlement.bp_b;
    json["policy"] = settlement.policy;
    return json;
}

auto submit=[&store](const httplib::Request& req,httplib::Response& res,bool version2){
    const auto record=study_meta::parse_record(req.body);
    if(!record){res.status=400;res.set_content("{\"error\":\"invalid\"}","application/json");return;}
    const auto result=store.put(*record);
    using Status=study_meta::SqlStatus;
    if(result.status==Status::accepted) {
        const study_meta::Settlement settlement{result.receipt,
            static_cast<std::uint32_t>(result.awards.a),static_cast<std::uint32_t>(result.awards.b),
            static_cast<std::uint32_t>(result.awards.policy)};
        const auto body=version2 ? study_meta::settlement_json(settlement)
                                 : study_meta::receipt_json(result.receipt);
        res.set_content(body.dump(),"application/json");
    }else {
        res.status=result.status==Status::conflict ? 409 : result.status==Status::storage_error ? 503 : 400;
        res.set_content("{\"error\":\"not_accepted\"}","application/json");
    }
};
http.Post("/study/v1/matches",[submit](const httplib::Request& req,httplib::Response& res){submit(req,res,false);});
http.Post("/study/v2/matches",[submit](const httplib::Request& req,httplib::Response& res){submit(req,res,true);});

inline std::optional<Settlement> parse_settlement(const std::string& body) {
    const std::optional<Json> parsed = object(body, 7);
    if (!parsed) {
        return std::nullopt;
    }
    const Json& json = *parsed;

    const std::optional<std::uint64_t> key = number(json, "key");
    const std::optional<std::uint64_t> row = number(json, "row");
    const std::optional<std::uint64_t> player_a = number(json, "player_a");
    const std::optional<std::uint64_t> player_b = number(json, "player_b");
    const std::optional<std::uint64_t> bp_a = number(json, "bp_a");
    const std::optional<std::uint64_t> bp_b = number(json, "bp_b");
    const std::optional<std::uint64_t> policy = number(json, "policy");
    if (!key || !row || !player_a || !player_b || !bp_a || !bp_b || !policy) {
        return std::nullopt;
    }

    // Identity and policy/award invariants, all still in std::uint64_t.
    if (*key == 0 || *row == 0 || *player_a == 0 || *player_b == 0) {
        return std::nullopt;
    }
    if (*player_a == *player_b) {
        return std::nullopt;
    }
    if (*policy > 1) {
        return std::nullopt;
    }
    if (!settlement_detail::awards_ok(*policy, *bp_a, *bp_b)) {
        return std::nullopt;
    }

    return Settlement{{*key, *row, *player_a, *player_b},
                      static_cast<std::uint32_t>(*bp_a),
                      static_cast<std::uint32_t>(*bp_b),
                      static_cast<std::uint32_t>(*policy)};
}

